(5122535, 746047, 42013, '<td valign="top">Winner! Love the silhouettes.</td>', 'Winner! Love the silhouettes.', '2008-12-10 12:19:10.000000', NULL, 1),
(5122537, 746083, 56254, '<td valign="top">having the harsh sunlight in the center of the frame forces my eyes to the lower left ... I can see the highlights in the leaves from your flash, which is a good thing.  I think that this image may have been stronger if you''d cropped out most of the harsh sunlight</td>', 'having the harsh sunlight in the center of the frame forces my eyes to the lower left ... I can see the highlights in the leaves from your flash, which is a good thing.  I think that this image may have been stronger if you''d cropped out most of the harsh sunlight', '2008-12-10 12:19:12.000000', NULL, 1),
(5122538, 746001, 42013, '<td valign="top">Very purplish-- I think I had this same sign in my sights about a year ago. :)</td>', 'Very purplish-- I think I had this same sign in my sights about a year ago. :)', '2008-12-10 12:19:14.000000', NULL, 1),
(5122543, 745135, 56254, '<td valign="top">wow, what gorgeous dogs ... the exposure is perfect!  Hard to accomplish with such dark animals against a dark background ... it''s my guess that this will make the front page ... good luck!</td>', 'wow, what gorgeous dogs ... the exposure is perfect!  Hard to accomplish with such dark animals against a dark background ... it''s my guess that this will make the front page ... good luck!', '2008-12-10 12:20:14.000000', NULL, 1),
(5122545, 746194, 56254, '<td valign="top">very pretty girl .. ... you''ve done a pretty good job with the fill flash,  but I think that this may have been even stronger if you''d had her tilt her head towards the flash, just slightly, to eliminate the harsh shadow on the side of her nose ...</td>', 'very pretty girl .. ... you''ve done a pretty good job with the fill flash,  but I think that this may have been even stronger if you''d had her tilt her head towards the flash, just slightly, to eliminate the harsh shadow on the side of her nose ...', '2008-12-10 12:21:50.000000', NULL, 1),
(5122550, 746154, 56254, '<td valign="top">nice job balancing out the backlighting with the fill flash ... colors are nice and vibrant!</td>', 'nice job balancing out the backlighting with the fill flash ... colors are nice and vibrant!', '2008-12-10 12:22:54.000000', NULL, 1),
