(5122555, 745876, 56254, '<td valign="top">what a cute dog!  nice job balancing the sunlight with the flash ... love the bokeh in the background, matches his eyes nicely!</td>', 'what a cute dog!  nice job balancing the sunlight with the flash ... love the bokeh in the background, matches his eyes nicely!', '2008-12-10 12:24:24.000000', NULL, 1),
(5122582, 746215, 75585, '<td valign="top">Absolutely gorgeous!!  Excellent capture and the tones on this are fantastic</td>', 'Absolutely gorgeous!!  Excellent capture and the tones on this are fantastic', '2008-12-10 12:39:24.000000', NULL, 1),
(5122618, 745890, 60614, '<td valign="top">I don''t know what to say but Absolutely gorgeous.  This has to be in the 6''s at least if not higher.  The blues just pop from the brown background and you did a wonderful job on your focus on the birds face.</td>', 'I don''t know what to say but Absolutely gorgeous.  This has to be in the 6''s at least if not higher.  The blues just pop from the brown background and you did a wonderful job on your focus on the birds face.', '2008-12-10 13:04:26.000000', NULL, 1),
