(5126490, 745135, 101117, '<td valign="top">Excellent use of fill flash, works wonderfully on their shiny coats. Love the expressions too!<br/> <br/>They''re gorgeous BTW!</td>', 'Excellent use of fill flash, works wonderfully on their shiny coats. Love the expressions too! They''re gorgeous BTW!', '2008-12-12 08:31:08.000000', NULL, 1),
(5126495, 746046, 101117, '<td valign="top">The use of fill flash is good, but the subject itself lets the picture down slightly. The bush / tree is uninteresting and actually distracts from a nice background. I think a few steps back so it didn''t fill quite so much of the frame would have helped here.</td>', 'The use of fill flash is good, but the subject itself lets the picture down slightly. The bush / tree is uninteresting and actually distracts from a nice background. I think a few steps back so it didn''t fill quite so much of the frame would have helped here.', '2008-12-12 08:32:54.000000', NULL, 1),
(5126505, 746107, 101117, '<td valign="top">This is a nice shot, good combination of a longish exposure time and fill flash to get the effect of the waves rolling in. Good detail on the rock also, there''s little in this image I can fault.<br/> <br/>Just one thing I would like to see, the nature of the image makes me want to see more across the horizon, it could have been good if the image was opened out a little more to the left and right.</td>', 'This is a nice shot, good combination of a longish exposure time and fill flash to get the effect of the waves rolling in. Good detail on the rock also, there''s little in this image I can fault. Just one thing I would like to see, the nature of the image makes me want to see more across the horizon, it could have been good if the image was opened out a little more to the left and right.', '2008-12-12 08:38:35.000000', NULL, 1),
(5126511, 746018, 101117, '<td valign="top">I like this shot, but think it''s just a little overexposed with the light coming through the window. My attention is drawn to the window and I end up looking out of it rather than at the bride. A faster shutter and use of the flash to make the bridge more prominent against the background could have helped here.</td>', 'I like this shot, but think it''s just a little overexposed with the light coming through the window. My attention is drawn to the window and I end up looking out of it rather than at the bride. A faster shutter and use of the flash to make the bridge more prominent against the background could have helped here.', '2008-12-12 08:41:23.000000', NULL, 1),
(5126513, 746155, 101117, '<td valign="top">While this is quite nice it''s not so much fill flash as use of a flash to freeze motion.</td>', 'While this is quite nice it''s not so much fill flash as use of a flash to freeze motion.', '2008-12-12 08:42:24.000000', NULL, 1),
(5126520, 745974, 101117, '<td valign="top">Good idea here, but I feel there''s a little too much in the frame. A couple of things I think might have improved the image:<br/> <br/>The white poster behind the model causes her to lose contrast, the dark wall is an idea backdrop to the skin tone of the model and it should have been left bare for the area behind her.<br/> <br/>The objects on the ground bring relevance, but they are untidy, perhaps stacking them against the crate or wall and making it a slightly tighter crop would have been good.<br/> <br/>Despite that, I still quite like this image for the mood of it.</td>', 'Good idea here, but I feel there''s a little too much in the frame. A couple of things I think might have improved the image: The white poster behind the model causes her to lose contrast, the dark wall is an idea backdrop to the skin tone of the model and it should have been left bare for the area behind her. The objects on the ground bring relevance, but they are untidy, perhaps stacking them against the crate or wall and making it a slightly tighter crop would have been good. Despite that, I still quite like this image for the mood of it.', '2008-12-12 08:45:58.000000', NULL, 1),
(5126523, 746221, 101117, '<td valign="top">He looks like he''s been caught sneaking a look at the presents!<br/> <br/>This is a good shot, but I think the white curtain to the left of the image is a little distracting and unnecessary. If the boy was just a touch to the left and then the remainder of the shot was cropped off I think this could have looked better.</td>', 'He looks like he''s been caught sneaking a look at the presents! This is a good shot, but I think the white curtain to the left of the image is a little distracting and unnecessary. If the boy was just a touch to the left and then the remainder of the shot was cropped off I think this could have looked better.', '2008-12-12 08:48:25.000000', NULL, 1),
(5126528, 746196, 101117, '<td valign="top">Great shot, really like this!<br/> <br/>Im assuming this was a longish exposure with a flash fired from the side to bring out a little detail in the grass.<br/> <br/>This has a great mood to it that just makes me look over and over again!</td>', 'Great shot, really like this! Im assuming this was a longish exposure with a flash fired from the side to bring out a little detail in the grass. This has a great mood to it that just makes me look over and over again!', '2008-12-12 08:50:33.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5126535, 745829, 101117, '<td valign="top">I feel the flash has been used here in a way that would typically be used to soften an image, but the look is a severe almost head mistress type! <br/> <br/>I think in this case it could have been good to emphasize some of the shadows to add to the stern look and maintain the mood of the shot.</td>', 'I feel the flash has been used here in a way that would typically be used to soften an image, but the look is a severe almost head mistress type!  I think in this case it could have been good to emphasize some of the shadows to add to the stern look and maintain the mood of the shot.', '2008-12-12 08:54:44.000000', NULL, 1),
(5126550, 746194, 101117, '<td valign="top">The flash here has caused the model to stand out of the image almost like she is standing in front of a poster. A little less fill flash and a little longer exposure would have helped here.<br/> <br/>Also, the background is slightly out of focus. I think in a shot like this it either has to be properly out of focus or in focus. The way it is it just detracts from the shot overall.</td>', 'The flash here has caused the model to stand out of the image almost like she is standing in front of a poster. A little less fill flash and a little longer exposure would have helped here. Also, the background is slightly out of focus. I think in a shot like this it either has to be properly out of focus or in focus. The way it is it just detracts from the shot overall.', '2008-12-12 08:58:47.000000', NULL, 1),
(5126553, 746001, 101117, '<td valign="top">This is a really interesting shot. The contrast between the red of the exit sign and the overall blue of the rest of the image works very well, and the strange angle makes me sit and tilt my head at it!<br/> <br/>Really like this, kept me looking at it for some time!</td>', 'This is a really interesting shot. The contrast between the red of the exit sign and the overall blue of the rest of the image works very well, and the strange angle makes me sit and tilt my head at it! Really like this, kept me looking at it for some time!', '2008-12-12 09:01:09.000000', NULL, 1),
(5126571, 746059, 101117, '<td valign="top">This shot has the potential to be very good, but there are a few things about it which take away from it.<br/> <br/>First is the strong sunlight on her hair, it makes me focus on that straight away rather than her eyes, which is a real shame because the eyes are very well done. The lighting from the right is nice, but it could have been better if it was diffused a little, perhaps even something as simple as through a white towel / sheet.<br/> <br/>Second is the large leaf, I don''t think it really serves any useful purpose here and seems to sit very out of context. The shot would probably have been better without it as the model is definitely enough to make the shot interesting on her own.<br/> <br/>Lastly, the white background to the left of the image is a touch distracting, not too bad because it''s blurred and not overly harsh, but it might have been worth seeing what the shot was like if you moved the composition to the right a little away from the light area.<br/> <br/>I am still giving this a 7 though, because despite what I have pointed out, I still feel it''s a very good portrait.</td>', 'This shot has the potential to be very good, but there are a few things about it which take away from it. First is the strong sunlight on her hair, it makes me focus on that straight away rather than her eyes, which is a real shame because the eyes are very well done. The lighting from the right is nice, but it could have been better if it was diffused a little, perhaps even something as simple as through a white towel / sheet. Second is the large leaf, I don''t think it really serves any useful purpose here and seems to sit very out of context. The shot would probably have been better without it as the model is definitely enough to make the shot interesting on her own. Lastly, the white background to the left of the image is a touch distracting, not too bad because it''s blurred and not overly harsh, but it might have been worth seeing what the shot was like if you moved the composition to the right a little away from the light area. I am still giving this a 7 though, because despite what I have pointed out, I still feel it''s a very good portrait.', '2008-12-12 09:10:50.000000', NULL, 1),
(5126581, 745946, 101117, '<td valign="top">Great concept, though I think the composition could have been a touch better.<br/> <br/>Perhaps if you moved backwards a bit to reduce the size of the shed and give it more of feeling of isolation in the snow, using a longer exposure and a little less fill flash, this would evoke much more feeling of cold / isolation.</td>', 'Great concept, though I think the composition could have been a touch better. Perhaps if you moved backwards a bit to reduce the size of the shed and give it more of feeling of isolation in the snow, using a longer exposure and a little less fill flash, this would evoke much more feeling of cold / isolation.', '2008-12-12 09:14:30.000000', NULL, 1),
(5126585, 745699, 58457, '<td valign="top">I like cross processing, but I don''t really feel it for this shot...  I think the contrast is pretty high, and your blues are nice, but the colors and shadows don''t seem to mesh with the expression on the girl.  I expect her to be more moody.  Maybe its just in my personal experience, most cross processed shots I''ve seen have been a bit grim or darker... good luck!</td>', 'I like cross processing, but I don''t really feel it for this shot...  I think the contrast is pretty high, and your blues are nice, but the colors and shadows don''t seem to mesh with the expression on the girl.  I expect her to be more moody.  Maybe its just in my personal experience, most cross processed shots I''ve seen have been a bit grim or darker... good luck!', '2008-12-12 09:17:43.000000', NULL, 1),
(5126586, 745825, 101117, '<td valign="top">Nothing is really in focus here, not sure if that was because of focus itself or down to camera shake, but it leaves my eye wandering round the picture looking for something to settle on, and I end up with the orange light at the end of the tunnel or the bright reflections along the top.<br/> <br/>Given the amount of reflective surfaces here, it probably isn''t the best place to get maximum advantage from a flash.</td>', 'Nothing is really in focus here, not sure if that was because of focus itself or down to camera shake, but it leaves my eye wandering round the picture looking for something to settle on, and I end up with the orange light at the end of the tunnel or the bright reflections along the top. Given the amount of reflective surfaces here, it probably isn''t the best place to get maximum advantage from a flash.', '2008-12-12 09:17:47.000000', NULL, 1),
(5126593, 745932, 101117, '<td valign="top">This is a really nice shot, the detail in the bird is great and background is very fitting.<br/> <br/>Just two comments. First is what looks like bread, which I''m assuming you used to attract the bird in the first place, it''s a little distracting in the scene, though I''m not too sure how you would avoid it. Second is that there is no gap between the tip of the birds wing and the edge of the frame. It would have been nice to have just a little more space there.<br/> <br/>Other than that, great shot, well done! 7 from me.</td>', 'This is a really nice shot, the detail in the bird is great and background is very fitting. Just two comments. First is what looks like bread, which I''m assuming you used to attract the bird in the first place, it''s a little distracting in the scene, though I''m not too sure how you would avoid it. Second is that there is no gap between the tip of the birds wing and the edge of the frame. It would have been nice to have just a little more space there. Other than that, great shot, well done! 7 from me.', '2008-12-12 09:21:14.000000', NULL, 1),
(5126597, 746150, 101117, '<td valign="top">This is nice, the combination of the fill flash giving detail and the lights in the background really appeal to me here.</td>', 'This is nice, the combination of the fill flash giving detail and the lights in the background really appeal to me here.', '2008-12-12 09:23:19.000000', NULL, 1),
(5126599, 745561, 101117, '<td valign="top">I love the title, so appropriate to the expression!</td>', 'I love the title, so appropriate to the expression!', '2008-12-12 09:25:34.000000', NULL, 1),
(5126600, 746172, 101117, '<td valign="top">Reminds me of a sketch Billy Connely does where he talks about the BLUE that outdoors people wear, the kind of blue you don''t find in nature.</td>', 'Reminds me of a sketch Billy Connely does where he talks about the BLUE that outdoors people wear, the kind of blue you don''t find in nature.', '2008-12-12 09:26:26.000000', NULL, 1),
(5126604, 745699, 101117, '<td valign="top">This image looks over processed and has resulted in some strange artifacts like the blue hand and odd skin tone.<br/> <br/>I do think the composition is good and there''s every chance the original could be more appealing than the one you have posted here.</td>', 'This image looks over processed and has resulted in some strange artifacts like the blue hand and odd skin tone. I do think the composition is good and there''s every chance the original could be more appealing than the one you have posted here.', '2008-12-12 09:28:12.000000', NULL, 1),
(5126605, 745406, 101117, '<td valign="top">Very nice picture, the B&amp;W works well here and the background frames the portrait very well without becoming distracting. Great shot!</td>', 'Very nice picture, the B&W works well here and the background frames the portrait very well without becoming distracting. Great shot!', '2008-12-12 09:29:22.000000', NULL, 1),
(5126608, 745449, 101117, '<td valign="top">Not really sure if any fill flash has been used here since the foreground is in darkness and the only light seems to be coming from the light itself. While I like the shot I don''t feel it particularly holds to the theme.</td>', 'Not really sure if any fill flash has been used here since the foreground is in darkness and the only light seems to be coming from the light itself. While I like the shot I don''t feel it particularly holds to the theme.', '2008-12-12 09:30:55.000000', NULL, 1),
(5126614, 745108, 101117, '<td valign="top">This is a very nice shot, and I feel the fill flash has been used very well to prevent the boy from not exposing at all against the harsh sunlight in the background.<br/> <br/>Also love the angle here. It''s just a shame you picked up a little lens flare, though that seems unavoidable given the angle of the sun! 7 from me.</td>', 'This is a very nice shot, and I feel the fill flash has been used very well to prevent the boy from not exposing at all against the harsh sunlight in the background. Also love the angle here. It''s just a shame you picked up a little lens flare, though that seems unavoidable given the angle of the sun! 7 from me.', '2008-12-12 09:33:05.000000', NULL, 1),
(5127273, 746087, 101533, '<td valign="top">Fantastic, superior in imagery</td>', 'Fantastic, superior in imagery', '2008-12-12 14:18:29.000000', NULL, 1),
(5127300, 746194, 42013, '<td valign="top">You''ve seamlessly balanced ambient light with flash. Good work. 8</td>', 'You''ve seamlessly balanced ambient light with flash. Good work. 8', '2008-12-12 14:35:26.000000', NULL, 1),
(5127301, 745108, 42013, '<td valign="top">I like the different perspective and the flares. Good work and should finish well.</td>', 'I like the different perspective and the flares. Good work and should finish well.', '2008-12-12 14:35:57.000000', NULL, 1),
(5127303, 746018, 42013, '<td valign="top">Perfectly lit portrait-- the fill flash is indistinguishable from the ambient light conditions. good work!</td>', 'Perfectly lit portrait-- the fill flash is indistinguishable from the ambient light conditions. good work!', '2008-12-12 14:36:31.000000', NULL, 1),
(5127304, 746107, 42013, '<td valign="top">Forground is perfect-- Wish the sky was toned down a little.</td>', 'Forground is perfect-- Wish the sky was toned down a little.', '2008-12-12 14:36:55.000000', NULL, 1),
(5127311, 746214, 42013, '<td valign="top">I like the pose but I feel as if the only light in this photo is from the flash(on board judging by the catch light in the center of his pupil). IMO, fill flash technique refers to balancing ambient light with the light on your subject- often to avoid silhouetting of the subject. You can soften the ''deer in headlights'' look by bouncing the flash off of a wall, ceiling, or other reflective object(friend in white shirt for example).</td>', 'I like the pose but I feel as if the only light in this photo is from the flash(on board judging by the catch light in the center of his pupil). IMO, fill flash technique refers to balancing ambient light with the light on your subject- often to avoid silhouetting of the subject. You can soften the ''deer in headlights'' look by bouncing the flash off of a wall, ceiling, or other reflective object(friend in white shirt for example).', '2008-12-12 14:40:23.000000', NULL, 1),
(5127347, 746172, 83785, '<td valign="top">Good use of fill flash, and for me the picture paints a story too, great.</td>', 'Good use of fill flash, and for me the picture paints a story too, great.', '2008-12-12 15:00:35.000000', NULL, 1),
(5127349, 746047, 83785, '<td valign="top">Fantastic picture and fill lighting use, great</td>', 'Fantastic picture and fill lighting use, great', '2008-12-12 15:01:28.000000', NULL, 1),
(5127358, 745874, 83785, '<td valign="top">nice picture, very sweet young girl :-).<br/>I have two comments, I think recomposing the picture to the rule of thirds, especially to remove the background wall would help to improve the picture.<br/>Also trying to decrease the depth of field to blur the tree a little more would be nice.</td>', 'nice picture, very sweet young girl :-).I have two comments, I think recomposing the picture to the rule of thirds, especially to remove the background wall would help to improve the picture.Also trying to decrease the depth of field to blur the tree a little more would be nice.', '2008-12-12 15:07:08.000000', NULL, 1),
(5127361, 744855, 83785, '<td valign="top">Some white card or a reflector to bounce some flash back in would improve the picture, but nice subject matter.</td>', 'Some white card or a reflector to bounce some flash back in would improve the picture, but nice subject matter.', '2008-12-12 15:09:24.000000', NULL, 1),
(5127362, 745825, 83785, '<td valign="top">Could have been a nice picture if it was in focus, nice colours.</td>', 'Could have been a nice picture if it was in focus, nice colours.', '2008-12-12 15:10:35.000000', NULL, 1),
(5127363, 746127, 83785, '<td valign="top">Nice picture :-)</td>', 'Nice picture :-)', '2008-12-12 15:11:15.000000', NULL, 1),
(5127365, 746124, 83785, '<td valign="top">Interesting picture, not sure what it is but it''s nice</td>', 'Interesting picture, not sure what it is but it''s nice', '2008-12-12 15:12:04.000000', NULL, 1),
(5127367, 746065, 83785, '<td valign="top">Nice idea for a pic</td>', 'Nice idea for a pic', '2008-12-12 15:13:07.000000', NULL, 1),
(5127368, 746119, 83785, '<td valign="top">Fantastic picture, hope it does well.</td>', 'Fantastic picture, hope it does well.', '2008-12-12 15:14:07.000000', NULL, 1),
(5127370, 746154, 83785, '<td valign="top">Nice picture, but I think it would look better if focused on a smaller region, such as just the green, yellow and red areas</td>', 'Nice picture, but I think it would look better if focused on a smaller region, such as just the green, yellow and red areas', '2008-12-12 15:15:59.000000', NULL, 1),
(5127371, 746155, 83785, '<td valign="top">Nice picture</td>', 'Nice picture', '2008-12-12 15:16:55.000000', NULL, 1),
(5127373, 746155, 9462, '<td valign="top">I like mine at night</td>', 'I like mine at night', '2008-12-12 15:17:34.000000', NULL, 1),
(5127375, 746011, 83785, '<td valign="top">Interesting picture, but it feels a bit jumbled to me.</td>', 'Interesting picture, but it feels a bit jumbled to me.', '2008-12-12 15:18:22.000000', NULL, 1),
(5127377, 746083, 9462, '<td valign="top">Make ''em into syrup!</td>', 'Make ''em into syrup!', '2008-12-12 15:19:07.000000', NULL, 1),
(5127378, 746128, 83785, '<td valign="top">Being a guy, is not seductive to me, lol</td>', 'Being a guy, is not seductive to me, lol', '2008-12-12 15:19:29.000000', NULL, 1),
(5127381, 746111, 83785, '<td valign="top">Nice picture</td>', 'Nice picture', '2008-12-12 15:20:02.000000', NULL, 1),
(5127383, 746173, 83785, '<td valign="top">Nice picture, may have looked better with more depth of field to see more of that nice sparkle</td>', 'Nice picture, may have looked better with more depth of field to see more of that nice sparkle', '2008-12-12 15:21:33.000000', NULL, 1),
(5127384, 746109, 83785, '<td valign="top">Nice picture</td>', 'Nice picture', '2008-12-12 15:22:04.000000', NULL, 1),
(5127385, 745176, 83785, '<td valign="top">Great picture!</td>', 'Great picture!', '2008-12-12 15:22:35.000000', NULL, 1),
(5127386, 746084, 83785, '<td valign="top">Lovely picture :-)</td>', 'Lovely picture :-)', '2008-12-12 15:23:22.000000', NULL, 1),
(5127389, 745359, 83785, '<td valign="top">Nice pic, but for me the floor the duck is standing on is a little distracting</td>', 'Nice pic, but for me the floor the duck is standing on is a little distracting', '2008-12-12 15:24:44.000000', NULL, 1),
(5127393, 745852, 83785, '<td valign="top">Fantastic picture, great use of fill flash</td>', 'Fantastic picture, great use of fill flash', '2008-12-12 15:25:52.000000', NULL, 1),
(5127395, 744722, 83785, '<td valign="top">Lovely picture, very cute and funny :-)</td>', 'Lovely picture, very cute and funny :-)', '2008-12-12 15:26:43.000000', NULL, 1),
(5127396, 745610, 83785, '<td valign="top">Unusual and interesting picture</td>', 'Unusual and interesting picture', '2008-12-12 15:27:58.000000', NULL, 1),
(5127397, 746161, 83785, '<td valign="top">Interesting texture</td>', 'Interesting texture', '2008-12-12 15:28:32.000000', NULL, 1),
(5127398, 746087, 83785, '<td valign="top">Nice colour and mood</td>', 'Nice colour and mood', '2008-12-12 15:29:08.000000', NULL, 1),
(5127399, 745699, 83785, '<td valign="top">Fantastic colour and the cross-processing really give the picture something</td>', 'Fantastic colour and the cross-processing really give the picture something', '2008-12-12 15:30:10.000000', NULL, 1),
(5127402, 745135, 83785, '<td valign="top">Nice picture, good fill flash lighting</td>', 'Nice picture, good fill flash lighting', '2008-12-12 15:31:40.000000', NULL, 1),
(5127408, 746107, 83785, '<td valign="top">Nice picture, shame there is so much cloud at the sunrise. Everytime I go to take sunset pics, there is always too much cloud at the sunset point, very irritating, lol</td>', 'Nice picture, shame there is so much cloud at the sunrise. Everytime I go to take sunset pics, there is always too much cloud at the sunset point, very irritating, lol', '2008-12-12 15:35:04.000000', NULL, 1),
(5127412, 746194, 83785, '<td valign="top">Fantastic picture</td>', 'Fantastic picture', '2008-12-12 15:36:00.000000', NULL, 1),
(5127414, 746025, 83785, '<td valign="top">Interesting picture, a bit more fill flash would have been nice</td>', 'Interesting picture, a bit more fill flash would have been nice', '2008-12-12 15:38:09.000000', NULL, 1),
(5127416, 744918, 83785, '<td valign="top">Cool picture, looks like my home London, the Southbank maybe. Funny, excellent!</td>', 'Cool picture, looks like my home London, the Southbank maybe. Funny, excellent!', '2008-12-12 15:40:18.000000', NULL, 1),
(5127417, 745890, 83785, '<td valign="top">Excellent! Very beautiful colour</td>', 'Excellent! Very beautiful colour', '2008-12-12 15:40:55.000000', NULL, 1),
(5127419, 746038, 83785, '<td valign="top">Fantastic picture, hope you do well with this</td>', 'Fantastic picture, hope you do well with this', '2008-12-12 15:41:34.000000', NULL, 1),
(5127420, 745108, 83785, '<td valign="top">Nice picture and perspective</td>', 'Nice picture and perspective', '2008-12-12 15:42:18.000000', NULL, 1),
(5127421, 746129, 83785, '<td valign="top">Nice family picture :-)</td>', 'Nice family picture :-)', '2008-12-12 15:42:53.000000', NULL, 1),
(5127423, 746202, 83785, '<td valign="top">Doesn''t look too well focused, may have looked better closer up</td>', 'Doesn''t look too well focused, may have looked better closer up', '2008-12-12 15:43:30.000000', NULL, 1),
(5127424, 745475, 83785, '<td valign="top">Nice picture, but is it fill flash? I guess it would be difficult to get closer to the shrubs to give those a lot of fill flash, and to get all of the hotel in the picture too.</td>', 'Nice picture, but is it fill flash? I guess it would be difficult to get closer to the shrubs to give those a lot of fill flash, and to get all of the hotel in the picture too.', '2008-12-12 15:45:29.000000', NULL, 1),
(5127425, 746182, 83785, '<td valign="top">Nice light trails, but having only a piece of boat in the foreground doesn''t work for me, sorry</td>', 'Nice light trails, but having only a piece of boat in the foreground doesn''t work for me, sorry', '2008-12-12 15:48:00.000000', NULL, 1),
(5127426, 745829, 83785, '<td valign="top">Fantastic picture</td>', 'Fantastic picture', '2008-12-12 15:48:22.000000', NULL, 1),
(5127498, 745406, 83785, '<td valign="top">Excellent photo, have a nice feeling about it</td>', 'Excellent photo, have a nice feeling about it', '2008-12-12 16:30:20.000000', NULL, 1),
(5127502, 745651, 83785, '<td valign="top">Oh my god.... ! shocking at first, but yes funny, :-)</td>', 'Oh my god.... ! shocking at first, but yes funny, :-)', '2008-12-12 16:32:34.000000', NULL, 1),
(5127514, 744936, 83785, '<td valign="top">Fantastic picture, funny but I have a friend who looks just like this guy, obviously without the staggered hair / beard. Hope this does well.</td>', 'Fantastic picture, funny but I have a friend who looks just like this guy, obviously without the staggered hair / beard. Hope this does well.', '2008-12-12 16:41:40.000000', NULL, 1),
